# -*- coding=utf-8 -*-

import re

# -------------------
# uma classe de exceção proprietária
class MyError(Exception):
    pass

class Personne:

    # construtor
    def __init__(self,prenom="x",nom="x",age=0):
         # o nome próprio não pode estar vazio
        match=re.match(r"^\s*(\S+)\s*$",prenom)
        if not match:
            raise MyError("Le prenom ne peut etre vide")
        else:
            self.prenom=match.groups()[0]
        # o apelido não pode estar vazio
        match=re.match(r"^\s*(\S+)\s*$",nom)
        if not match:
            raise MyError("Le nom ne peut etre vide")
        else:
            self.nom=match.groups()[0]
        # a idade deve ser válida
        match=re.match(r"^\s*(\d+)\s*$",str(age))
        if not match:
            raise MyError("l'age doit etre un entier positif")
        else:
            self.age=match.groups()[0]

    def __str__(self):
        return "[{0},{1},{2}]".format(self.prenom,self.nom,self.age)

# ---------------------------------- mão
# um objeto Pessoa
try:
    p=Personne("  Paul  ","  Langevin  ",48)
    print "personne={0}".format(p)
except MyError, erreur:
    print erreur
# outro objeto Pessoa
try:
    p=Personne("  xx  ","  yy  ","  zz")
    print "personne={0}".format(p)
except MyError, erreur:
    print erreur
# outra pessoa
try:
    p=Personne()
    print "personne={0}".format(p)
except MyError, erreur:
    print erreur
</code></pre> <p>Notas:</p> <ul> <li>linhas 7-8: uma classe MyError derivada da classe Exception. Não acrescenta qualquer funcionalidade a esta última. Existe apenas para ter uma exceção própria;</li> <li>linha 13: o construtor tem valores por predefinição para os seus parâmetros. Assim, a operação p=Personne() é equivalente a p=Pessoa("x", "x", 0);</li> <li>linhas 15-9: analisamos o parâmetro prenom. Este deve ser diferente de vazio. Caso contrário, lançamos a exceção MyError com uma mensagem de erro;</li> <li>linhas 21-25: o mesmo se aplica ao nome;</li> <li>linhas 27-31: verificação da idade;</li> <li>linhas 33-34: a função __str__ substitui o método anteriormente denominado identite;</li> <li>linhas 38-42: instância de uma pessoa e, em seguida, exibição da sua identidade;</li> <li>linha 39: instância;</li> <li>linha 40: exibição. A operação solicita a exibição da pessoa p sob a forma de uma cadeia de caracteres. O interpretador Python chama então automaticamente o método p.__str__(), caso este exista. Este método desempenha a mesma função que o método toString() em Java ou nas linguagens .NET;</li> <li>linhas 41-42: tratamento de uma eventual exceção do tipo MyError. Em seguida, exibe a mensagem de erro associada à exceção;</li> <li>linhas 44-48: o mesmo se aplica a uma segunda pessoa instanciada com parâmetros errados;</li> <li>linhas 50-54: o mesmo se aplica a uma terceira pessoa instanciada com os parâmetros por predefinição.</li> </ul> Resultados <pre><code>personne=[Paul,Langevin,48]
l'age doit etre un entier positif
personne=[x,x,0]
</code></pre> <p></p>

