# -*- coding=utf-8 -*-

import re

# -------------------
# uma classe de exceção proprietária
class MyError(Exception):
    pass

class Personne:
    # atributos da classe
    # não declarados — podem ser criados dinamicamente

    # construtor
    def __init__(self,prenom="x",nom="x",age=0):
         # o nome próprio não pode estar vazio
        match=re.match(r"^\s*(\S+)\s*$",prenom)
        if not match:
            raise MyError("Le prenom ne peut etre vide")
        else:
            self.prenom=match.groups()[0]
        # o apelido não pode estar em branco
        match=re.match(r"^\s*(\S+)\s*$",nom)
        if not match:
            raise MyError("Le nom ne peut etre vide")
        else:
            self.nom=match.groups()[0]
            # a idade deve ser válida
        match=re.match(r"^\s*(\d+)\s*$",str(age))
        if not match:
            raise MyError("l'age doit etre un entier positif")
        else:
            self.age=match.groups()[0]

    def initWithPersonne(self,p):
        # inicializa o objeto atual com uma pessoa p
        self.__init__(p.prenom,p.nom,p.age)

    def __str__(self):
        return "[{0},{1},{2}]".format(self.prenom,self.nom,self.age)

# ---------------------------------- main
# um objeto Pessoa
try:
    p0=Personne("  Paul  ","  Langevin  ",48)
    print "personne={0}".format(p0)
except MyError, erreur:
    print erreur
# outro objeto Pessoa
try:
    p1=Personne("  xx  ","  yy  ","  zz")
    print "personne={0}".format(p1)
except MyError, erreur:
    print erreur
# outra pessoa
p2=Personne()
try:
    p2.initWithPersonne(p0)
    print "personne={0}".format(p2)
except MyError, erreur:
    print erreur

</code></pre> <p>Notas:</p> <ul> <li>a diferença em relação ao script anterior está nas linhas 35-37. Foi adicionado o método initWithPersonne. Este recorre ao construtor __init__. Não é possível, tal como nas linguagens tipadas, ter métodos com o mesmo nome diferenciados pela natureza dos seus parâmetros ou do seu resultado. Por conseguinte, não é possível ter vários construtores que criem o objeto a partir de parâmetros diferentes, neste caso um objeto do tipo Personne.</li> </ul> Resultados <pre><code>personne=[Paul,Langevin,48]
l'age doit etre un entier positif
personne=[Paul,Langevin,48]
</code></pre> <p></p>

