# -*- coding=utf-8 -*-

import re

class Personne:
    ...

class Enseignant(Personne):
    def __init__(self,prenom="x",nom="x",age=0,discipline="x"):
        Personne.__init__(self,prenom,nom,age)
        self.discipline=discipline

    def __str__(self):
        return "[{0},{1},{2},{3}]".format(self.prenom,self.nom,self.age,self.discipline)


# ---------------------------------- mão
# criação de uma lista de objetos «Pessoa» e derivados
groupe=[Enseignant("Paul","Langevin",48,"anglais"), Personne("Sylvie","Lefur",70)]
# identidade dessas pessoas
for i in range(len(groupe)):
  print "groupe[{0}]={1}".format(i,groupe[i])

</code></pre> <p>Notas:</p> <ul> <li>linhas 5-6: a classe Personne já está definida;</li> <li>linha 8: declara a classe Enseignant como uma classe derivada da classe Pessoa;</li> <li>linha 10: o construtor da classe derivada Enseignant deve chamar o construtor da classe pai Personne;</li> <li>linhas 21-22: para apresentar o grupo[i], o interpretador utiliza o método grupo[i].__str__(). O método __str__() utilizado é o da classe real de grupo[i], tal como  mostram os resultados abaixo.</li> </ul> Resultados <pre><code>groupe[0]=[Paul,Langevin,48,anglais]
groupe[1]=[Sylvie,Lefur,70]
</code></pre> <p></p>

